import json

with open('/app/stats.json') as f:
    s = json.load(f)

ov = s['overview']
ca = s['color_advantage']
ra = s['rating']
op = s['openings']
tc = s['time_control']

# Helper to make Chart.js bar chart
def bar_chart(chart_id, labels, datasets, title='', y_label='', stacked=False, height=400):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    stacked_js = 'true' if stacked else 'false'
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'bar',
  data: {{ labels: {labels_js}, datasets: {ds_js} }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
    scales: {{
      x: {{ stacked: {stacked_js} }},
      y: {{ stacked: {stacked_js}, beginAtZero: true, title: {{ display: {'true' if y_label else 'false'}, text: {json.dumps(y_label)} }} }}
    }}
  }}
}});
</script>'''

def hbar_chart(chart_id, labels, datasets, title='', x_label='', height=450):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'bar',
  data: {{ labels: {labels_js}, datasets: {ds_js} }},
  options: {{
    indexAxis: 'y',
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
    scales: {{
      x: {{ beginAtZero: true, title: {{ display: {'true' if x_label else 'false'}, text: {json.dumps(x_label)} }} }}
    }}
  }}
}});
</script>'''

def line_chart(chart_id, labels, datasets, title='', y_label='', height=350):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'line',
  data: {{ labels: {labels_js}, datasets: {ds_js} }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
    scales: {{
      y: {{ beginAtZero: false, title: {{ display: {'true' if y_label else 'false'}, text: {json.dumps(y_label)} }} }}
    }}
  }}
}});
</script>'''

def doughnut_chart(chart_id, labels, data, colors, title='', height=300):
    return f'''<div style="max-width:450px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'doughnut',
  data: {{ labels: {json.dumps(labels)}, datasets: [{{ data: {json.dumps(data)}, backgroundColor: {json.dumps(colors)}, borderWidth: 1 }}] }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'bottom' }} }}
  }}
}});
</script>'''


# Build the HTML
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Lichess Chess Game Analytics</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f1923;
    --surface: #1a2634;
    --surface2: #243447;
    --border: #2d4a5e;
    --text: #e8edf2;
    --text-muted: #8fa3b8;
    --accent: #4fc3f7;
    --accent2: #81d4fa;
    --white-piece: #f5f5f5;
    --black-piece: #455a64;
    --draw-color: #78909c;
    --green: #66bb6a;
    --red: #ef5350;
    --amber: #ffa726;
  }}
  *, *::before, *::after {{ box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
    margin: 0; padding: 0;
    line-height: 1.7;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 2rem 4rem; }}
  header {{
    background: linear-gradient(135deg, #1a2634 0%, #0d253a 50%, #1a3a5c 100%);
    border-bottom: 3px solid var(--accent);
    padding: 3rem 2rem 2.5rem;
    text-align: center;
  }}
  header h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    margin: 0 0 0.5rem;
    color: var(--accent2);
    letter-spacing: -0.5px;
  }}
  header .subtitle {{
    color: var(--text-muted);
    font-size: 1.1rem;
    max-width: 700px;
    margin: 0 auto;
  }}
  header .meta {{
    margin-top: 1.2rem;
    font-size: 0.85rem;
    color: var(--text-muted);
  }}
  header .meta span {{ margin: 0 0.8rem; }}
  h2 {{
    font-size: 1.65rem;
    color: var(--accent);
    margin: 3rem 0 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid var(--border);
  }}
  h3 {{
    font-size: 1.2rem;
    color: var(--accent2);
    margin: 2rem 0 0.8rem;
  }}
  p {{ margin: 0.8rem 0; color: var(--text); }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1rem;
    margin: 1.5rem 0;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 1.3rem;
    text-align: center;
  }}
  .kpi-card .value {{
    font-size: 2rem;
    font-weight: 700;
    color: var(--accent);
  }}
  .kpi-card .label {{
    font-size: 0.82rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 0.3rem;
  }}
  .kpi-card.white-card .value {{ color: var(--white-piece); }}
  .kpi-card.black-card .value {{ color: var(--draw-color); }}
  .kpi-card.draw-card .value {{ color: var(--amber); }}
  .kpi-card.green-card .value {{ color: var(--green); }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 1.2rem 0;
    font-size: 0.9rem;
  }}
  th, td {{
    padding: 0.7rem 0.9rem;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  th {{
    background: var(--surface2);
    color: var(--accent2);
    font-weight: 600;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }}
  tr:hover td {{ background: var(--surface); }}
  td.num {{ text-align: right; font-variant-numeric: tabular-nums; }}
  .highlight {{ color: var(--accent); font-weight: 600; }}
  .callout {{
    background: var(--surface);
    border-left: 4px solid var(--accent);
    padding: 1rem 1.3rem;
    margin: 1.5rem 0;
    border-radius: 0 8px 8px 0;
  }}
  .callout.warning {{ border-left-color: var(--amber); }}
  .callout.success {{ border-left-color: var(--green); }}
  .finding {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 1.2rem 1.5rem;
    margin: 1rem 0;
  }}
  .finding h4 {{
    margin: 0 0 0.5rem;
    color: var(--accent2);
    font-size: 1.05rem;
  }}
  .bar-inline {{
    display: flex;
    height: 28px;
    border-radius: 6px;
    overflow: hidden;
    margin: 0.5rem 0;
  }}
  .bar-inline .seg {{
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.78rem;
    font-weight: 600;
    color: #1a1a1a;
  }}
  .badge {{
    display: inline-block;
    padding: 0.15rem 0.55rem;
    border-radius: 4px;
    font-size: 0.78rem;
    font-weight: 600;
  }}
  .badge-white {{ background: var(--white-piece); color: #1a1a1a; }}
  .badge-black {{ background: var(--black-piece); color: #fff; }}
  .badge-draw {{ background: var(--draw-color); color: #fff; }}
  footer {{
    text-align: center;
    padding: 2rem;
    color: var(--text-muted);
    font-size: 0.85rem;
    border-top: 1px solid var(--border);
    margin-top: 3rem;
  }}
  .toc {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 1.5rem 2rem;
    margin: 2rem 0;
  }}
  .toc h3 {{ margin-top: 0; }}
  .toc ol {{ padding-left: 1.2rem; }}
  .toc a {{ color: var(--accent); text-decoration: none; }}
  .toc a:hover {{ text-decoration: underline; }}
  .flex-row {{ display: flex; gap: 1.5rem; flex-wrap: wrap; margin: 1rem 0; }}
  .flex-row > div {{ flex: 1; min-width: 280px; }}
  @media (max-width: 700px) {{
    header h1 {{ font-size: 1.5rem; }}
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .flex-row {{ flex-direction: column; }}
  }}
</style>
</head>
<body>

<header>
  <h1>Lichess Chess Game Analytics</h1>
  <p class="subtitle">Patterns of Victory, Openings, and Player Dynamics &mdash; A comprehensive analysis of {ov['total_games']:,} chess games</p>
  <div class="meta">
    <span>Dataset: {ov['total_games']:,} games</span>
    <span>Source: Lichess.org</span>
    <span>Report generated: April 2026</span>
  </div>
</header>

<div class="container">

<nav class="toc">
  <h3>Table of Contents</h3>
  <ol>
    <li><a href="#overview">Dataset Overview &amp; Game Distribution</a></li>
    <li><a href="#color-advantage">White vs. Black: The First-Move Advantage</a></li>
    <li><a href="#rating-analysis">Rating Dynamics and Their Impact on Outcomes</a></li>
    <li><a href="#opening-strategy">Opening Analysis: Popular Openings and Their Success Rates</a></li>
    <li><a href="#time-control">Time Control Patterns and Game Characteristics</a></li>
    <li><a href="#key-findings">Key Findings and Strategic Takeaways</a></li>
  </ol>
</nav>

<!-- ============================================================= -->
<!-- SECTION 1: OVERVIEW -->
<!-- ============================================================= -->
<h2 id="overview">1. Dataset Overview &amp; Game Distribution</h2>

<p>This analysis covers <strong>{ov['total_games']:,}</strong> chess games played on <a href="https://lichess.org" style="color:var(--accent)">Lichess.org</a>. The dataset captures a representative cross-section of online chess activity, ranging from beginner-level encounters to games between strong club players.</p>

<div class="kpi-grid">
  <div class="kpi-card">
    <div class="value">{ov['total_games']:,}</div>
    <div class="label">Total Games</div>
  </div>
  <div class="kpi-card">
    <div class="value">{ov['rated_pct']}%</div>
    <div class="label">Rated Games</div>
  </div>
  <div class="kpi-card">
    <div class="value">{ov['avg_turns']}</div>
    <div class="label">Avg Turns (Half-moves)</div>
  </div>
  <div class="kpi-card">
    <div class="value">{ov['median_turns']}</div>
    <div class="label">Median Turns</div>
  </div>
</div>

<h3>Winner Distribution</h3>

<div class="kpi-grid">
  <div class="kpi-card white-card">
    <div class="value">{ov['white_win_pct']}%</div>
    <div class="label">White Wins ({ov['white_wins']:,})</div>
  </div>
  <div class="kpi-card black-card">
    <div class="value">{ov['black_win_pct']}%</div>
    <div class="label">Black Wins ({ov['black_wins']:,})</div>
  </div>
  <div class="kpi-card draw-card">
    <div class="value">{ov['draw_pct']}%</div>
    <div class="label">Draws ({ov['draws']:,})</div>
  </div>
</div>

<div class="bar-inline">
  <div class="seg" style="width:{ov['white_win_pct']}%;background:var(--white-piece);">{ov['white_win_pct']}%</div>
  <div class="seg" style="width:{ov['black_win_pct']}%;background:var(--black-piece);color:#fff;">{ov['black_win_pct']}%</div>
  <div class="seg" style="width:{ov['draw_pct']}%;background:var(--draw-color);color:#fff;">{ov['draw_pct']}%</div>
</div>

<h3>How Games End</h3>

<p>The vast majority of games end decisively. Resignation is the most common outcome at <strong>{ov['victory_status_pct']['resign']}%</strong>, followed by checkmate at <strong>{ov['victory_status_pct']['mate']}%</strong>. Only <strong>{ov['victory_status_pct']['draw']}%</strong> of games end in a draw &mdash; far below the ~30% draw rate seen in professional over-the-board chess, reflecting the more aggressive, risk-taking nature of online play.</p>

{doughnut_chart('chart_victory_status',
    list(ov['victory_status'].keys()),
    list(ov['victory_status'].values()),
    ['#ef5350', '#66bb6a', '#ffa726', '#78909c'],
    'Victory Status Distribution')}

<table>
  <tr><th>Victory Status</th><th class="num">Games</th><th class="num">Percentage</th></tr>
  <tr><td>Resignation</td><td class="num">{ov['victory_status']['resign']:,}</td><td class="num">{ov['victory_status_pct']['resign']}%</td></tr>
  <tr><td>Checkmate</td><td class="num">{ov['victory_status']['mate']:,}</td><td class="num">{ov['victory_status_pct']['mate']}%</td></tr>
  <tr><td>Out of Time</td><td class="num">{ov['victory_status']['outoftime']:,}</td><td class="num">{ov['victory_status_pct']['outoftime']}%</td></tr>
  <tr><td>Draw</td><td class="num">{ov['victory_status']['draw']:,}</td><td class="num">{ov['victory_status_pct']['draw']}%</td></tr>
</table>

<!-- ============================================================= -->
<!-- SECTION 2: COLOR ADVANTAGE -->
<!-- ============================================================= -->
<h2 id="color-advantage">2. White vs. Black: The First-Move Advantage</h2>

<div class="callout">
  <strong>Key Finding:</strong> Among the {ca['decisive_games']:,} decisive games (excluding draws), White wins <strong>{ca['white_win_decisive_pct']}%</strong> vs. Black's <strong>{ca['black_win_decisive_pct']}%</strong> &mdash; a <strong>{round(ca['white_win_decisive_pct'] - ca['black_win_decisive_pct'], 2)} percentage-point edge</strong> attributable to the first-move advantage.
</div>

<p>The first-move advantage is one of the most debated topics in chess theory. In this dataset, white's edge is clear but moderate: roughly <strong>52&ndash;48</strong> among decisive games. This is consistent with historical data from both online and over-the-board play, where white typically wins 52&ndash;56% of decisive games.</p>

<h3>White's Edge by Victory Type</h3>

<p>White's advantage manifests differently depending on how the game ends:</p>

<table>
  <tr><th>Victory Type</th><th class="num">White Win%</th><th class="num">Black Win%</th><th class="num">White Edge</th></tr>'''

for vs_key, vs_label in [('mate', 'Checkmate'), ('resign', 'Resignation'), ('outoftime', 'Out of Time')]:
    v = ca['by_victory_status'].get(vs_key, {})
    edge = round(v.get('white_pct', 0) - v.get('black_pct', 0), 2)
    edge_str = f'+{edge}' if edge > 0 else str(edge)
    html += f'''
  <tr><td>{vs_label}</td><td class="num">{v.get('white_pct', 0)}%</td><td class="num">{v.get('black_pct', 0)}%</td><td class="num">{edge_str} pp</td></tr>'''

html += '''
</table>'''

# Chart: Color advantage by victory status
vs_labels = ['Checkmate', 'Resignation', 'Out of Time']
vs_white = [ca['by_victory_status'].get(k, {}).get('white_pct', 0) for k in ['mate', 'resign', 'outoftime']]
vs_black = [ca['by_victory_status'].get(k, {}).get('black_pct', 0) for k in ['mate', 'resign', 'outoftime']]

html += bar_chart('chart_color_vstatus', vs_labels, [
    {'label': 'White Win %', 'data': vs_white, 'backgroundColor': '#e0e0e0', 'borderRadius': 4},
    {'label': 'Black Win %', 'data': vs_black, 'backgroundColor': '#546e7a', 'borderRadius': 4},
], 'White vs. Black Win Rate by Victory Type', 'Win Rate (%)')

html += '''
<h3>White's Advantage by Rating Bracket</h3>

<p>A critical question: does white's advantage hold across all skill levels, or does it concentrate at certain rating ranges? The data shows a remarkably consistent pattern, with white's edge slightly <strong>narrowing at higher ratings</strong> as players become better at equalizing with black.</p>

<table>
  <tr><th>Rating Bracket</th><th class="num">Games</th><th class="num">White Win%</th><th class="num">Black Win%</th><th class="num">Draw%</th><th class="num">White Edge</th></tr>'''

bracket_labels = []
bracket_white = []
bracket_black = []
bracket_draw = []
