# Helper to make Chart.js bar chart
def bar_chart(chart_id, labels, datasets, title='', y_label='', stacked=False, height=400):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    stacked_js = 'true' if stacked else 'false'
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'bar',
  data: {{ labels: {labels_js}, datasets: {ds_js} }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
    scales: {{
      x: {{ stacked: {stacked_js} }},
      y: {{ stacked: {stacked_js}, beginAtZero: true, title: {{ display: {'true' if y_label else 'false'}, text: {json.dumps(y_label)} }} }}
    }}
  }}
}});
</script>'''

def hbar_chart(chart_id, labels, datasets, title='', x_label='', height=450):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
