    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
    scales: {{
      x: {{ beginAtZero: true, title: {{ display: {'true' if x_label else 'false'}, text: {json.dumps(x_label)} }} }}
    }}
  }}
}});
</script>'''

def line_chart(chart_id, labels, datasets, title='', y_label='', height=350):
    labels_js = json.dumps(labels)
    ds_js = json.dumps(datasets)
    return f'''<div style="max-width:800px;margin:1.5em auto;"><canvas id="{chart_id}" height="{height}"></canvas></div>
<script>
new Chart(document.getElementById('{chart_id}'), {{
  type: 'line',
  data: {{ labels: {labels_js}, datasets: {ds_js} }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: {'true' if title else 'false'}, text: {json.dumps(title)}, font: {{ size: 15 }} }}, legend: {{ position: 'top' }} }},
