      y: {{ beginAtZero: false, title: {{ display: {'true' if y_label else 'false'}, text: {json.dumps(y_label)} }} }}
    }}
  }}
}});
</script>'''

def doughnut_chart(chart_id, labels, data, colors, title='', height=300):
