    tc_white_color.append(tv['white_pct'])
    tc_black_color.append(tv['black_pct'])

html += '''
</table>'''

html += bar_chart('chart_color_tc', tc_labels_color, [
    {'label': 'White Win %', 'data': tc_white_color, 'backgroundColor': '#e0e0e0', 'borderRadius': 4},
    {'label': 'Black Win %', 'data': tc_black_color, 'backgroundColor': '#546e7a', 'borderRadius': 4},
], 'White vs. Black Win Rate by Time Control (Decisive Games)', 'Win Rate (%)')

html += f'''
<p>Rapid games show the highest white advantage at <strong>+{round(ca['by_time_control'].get('Rapid',{}).get('white_pct',0) - ca['by_time_control'].get('Rapid',{}).get('black_pct',0), 1)} pp</strong>, while Classical games narrow to <strong>+{round(ca['by_time_control'].get('Classical',{}).get('white_pct',0) - ca['by_time_control'].get('Classical',{}).get('black_pct',0), 1)} pp</strong>. The dataset is heavily concentrated in Blitz ({ca['by_time_control'].get('Blitz',{}).get('games',0):,} games), where white's edge is <strong>+{round(ca['by_time_control'].get('Blitz',{}).get('white_pct',0) - ca['by_time_control'].get('Blitz',{}).get('black_pct',0), 1)} pp</strong>.</p>
'''

# ====== SECTION 3: RATING ANALYSIS ======
html += f'''
<h2 id="rating-analysis">3. Rating Dynamics and Their Impact on Outcomes</h2>

<h3>Rating Distribution</h3>

<p>Player ratings in this dataset span from <strong>{ra['white_min']}</strong> to <strong>{ra['white_max']}</strong> for white and <strong>{ra['black_min']}</strong> to <strong>{ra['black_max']}</strong> for black. The average rating is approximately <strong>{ra['white_mean']}</strong> (white) and <strong>{ra['black_mean']}</strong> (black), centering this population firmly in the intermediate player range.</p>

