    <div class="label">Rating Range</div>
  </div>
</div>
'''

# Rating histogram
hist = ra['histogram']
hist_labels = sorted(hist.keys(), key=lambda x: int(x.split(',')[0].strip('(').strip()))
hist_values = [hist[k] for k in hist_labels]
clean_labels = []
for k in hist_labels:
    parts = k.strip('()[]').split(',')
