html += '''
</table>'''

html += line_chart('chart_gap_winrate', gap_labels, [
    {'label': 'Higher-Rated Player Win %', 'data': gap_pcts, 'borderColor': '#66bb6a', 'backgroundColor': 'rgba(102,187,106,0.15)', 'fill': True, 'tension': 0.3, 'pointRadius': 6, 'pointBackgroundColor': '#66bb6a'},
], 'Win Probability vs. Rating Gap', 'Win Rate (%)', height=350)

html += '''
<h3>White Win Rate by Rating Differential Bin</h3>

<p>Looking at it from white's perspective: how does white's raw win rate shift when white is higher-rated vs. lower-rated?</p>

